"""All document content is generated by this project for qualification."""

import io


def office_fixture(extension):
    output = io.BytesIO()
    if extension == "docx":
        from docx import Document

        document = Document()
        document.add_heading("FileNimble fixture", 0)
        document.add_paragraph("Unicode café résumé. First page.")
        table = document.add_table(rows=3, cols=2)
        for row, values in zip(
            table.rows, (("Item", "Amount"), ("Alpha", "12"), ("Beta", "34")), strict=True
        ):
            for cell, value in zip(row.cells, values, strict=True):
                cell.text = value
        document.add_page_break()
        document.add_heading("Second page", 1)
        document.add_paragraph("End of owned document.")
        document.save(output)
    elif extension == "pptx":
        from pptx import Presentation

        presentation = Presentation()
        for title in ("First slide café", "Second slide résumé"):
            slide = presentation.slides.add_slide(presentation.slide_layouts[1])
            slide.shapes.title.text = title
            slide.placeholders[1].text = "Project-owned slide content"
            for shape in slide.shapes:
                if shape.has_text_frame:
                    for paragraph in shape.text_frame.paragraphs:
                        for run in paragraph.runs:
                            run.font.name = "Liberation Sans"
        presentation.save(output)
    else:
        from openpyxl import Workbook

        workbook = Workbook()
        for index, name in enumerate(("First sheet", "Second sheet")):
            sheet = workbook.active if index == 0 else workbook.create_sheet()
            sheet.title = name
            sheet.append([name, "Amount"])
            sheet.append(["Alpha café", 12])
            sheet.append(["Beta", 34])
            sheet.print_options.horizontalCentered = True
            sheet.print_area = "A1:B3"
            sheet.column_dimensions["A"].width = 24
            sheet.column_dimensions["B"].width = 16
        workbook.save(output)
    return output.getvalue()


